 dxfButton.addEventListener('click',()=>dxfInput.click());dxfInput.addEventListener('change',async()=>{const file=dxfInput.files?.[0];if(!file)return;try{const profiles=dxfPolylines(await file.text());if(!profiles.length)throw new Error('Polyline atau LWPolyline tidak ditemukan.');const range=profile=>Math.max(...profile.map(p=>p.x))-Math.min(...profile.map(p=>p.x)),imported=[...profiles].sort((a,b)=>range(b)-range(a)||b.length-a.length)[0],minX=Math.min(...imported.map(p=>p.x)),minZ=Math.min(...imported.map(p=>p.z));points=imported.map(p=>({x:+(p.x-minX).toFixed(2),z:+(p.z-minZ).toFixed(2)})).sort((a,b)=>a.x-b.x);const maxX=Math.max(...points.map(p=>p.x)),maxZ=Math.max(...points.map(p=>p.z)),autoMinZ=Math.min(0,...points.map(p=>p.z))-Math.max(.25,maxZ*.18);drawingWidth.value=(maxX+1).toFixed(2);drawingMinElevation.value=autoMinZ.toFixed(2);drawingMaxElevation.value=(maxZ+1).toFixed(2);dxfStatus.textContent=`DXF ${file.name}: ${points.length} titik dipakai (pembulatan 2 angka desimal). Area kerja otomatis X 0–${drawingWidth.value} m dan Z ${drawingMinElevation.value}–${drawingMaxElevation.value} m.`;dxfStatus.classList.remove('d-none');render()}catch(error){alert(`Impor DXF gagal: ${error.message}`)}finally{dxfInput.value=''}});
 const simulationBox=document.querySelector('#webSimulation'),simulationPlay=document.querySelector('#simulationPlay'),simulationReset=document.querySelector('#simulationReset'),simulationSpeed=document.querySelector('#simulationSpeed'),simulationStatus=document.querySelector('#simulationStatus'),simulationSpeedLabel=document.querySelector('#simulationSpeedLabel');
