 const soilBand=(ordered,b,showColor,showHatch)=>{if(ordered.length<2||(!showColor&&!showHatch))return'';const top=ordered.map(point=>project(point,b)),offset=22,bottom=top.map((point,index)=>{const before=top[Math.max(0,index-1)],after=top[Math.min(top.length-1,index+1)],dx=after.x-before.x,dy=after.y-before.y,length=Math.hypot(dx,dy)||1;return{x:point.x-dy/length*offset,y:point.y+dx/length*offset}}),contour=[...top,...bottom.slice().reverse()].map(point=>`${point.x},${point.y}`).join(' '),base=showColor?`<polygon points="${contour}" fill="#eadcc8" fill-opacity=".7"/>`:'',hatch=showHatch?`<defs><pattern id="soilHatch" width="14" height="14" patternUnits="userSpaceOnUse"><path d="M-4 4L4-4M0 14L14 0M10 18L18 10M-4 10L4 18M0 0L14 14M10-4L18 4" stroke="#795a3a" stroke-width="1"/></pattern></defs><polygon points="${contour}" fill="url(#soilHatch)" fill-opacity=".9"/>`:'';return base+hatch};
